from defusedxml import minidom
doc = minidom.parse('unpacked/word/document.xml')
body = doc.getElementsByTagName('w:body')[0]
def text(el):
    out = []
    for t in el.getElementsByTagName('w:t'):
        if t.firstChild is not None:
            out.append(t.firstChild.data)
    return ''.join(out)
for i, child in enumerate(body.childNodes):
    if child.nodeType == child.ELEMENT_NODE and child.tagName == 'w:p':
        ppr = child.getElementsByTagName('w:pStyle')
        style = ppr[0].getAttribute('w:val') if ppr else ''
        print(f"[{i}] style={style!r}: {text(child)!r}")
    elif child.nodeType == child.ELEMENT_NODE:
        print(f"[{i}] <{child.tagName}>")
EOF
